CREATE TABLE IF NOT EXISTS commercial_workspace_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL, organization text NOT NULL, plan text NOT NULL, status text NOT NULL DEFAULT 'PENDING', workspace_id uuid, created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz);
CREATE TABLE IF NOT EXISTS commercial_workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization text NOT NULL, plan text NOT NULL, status text NOT NULL DEFAULT 'ACTIVE', created_from_request uuid REFERENCES commercial_workspace_requests(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS commercial_workspace_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES commercial_workspaces(id), email text NOT NULL, display_name text, role text NOT NULL DEFAULT 'MEMBER', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS commercial_onboarding_checklists (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES commercial_workspaces(id), items jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS commercial_workspace_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES commercial_workspaces(id), action text NOT NULL, actor text, created_at timestamptz NOT NULL DEFAULT now());